const ExcelJS = require('exceljs');

async function main() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Extracted Text');

  // Add headers with styling
  sheet.columns = [
    { header: 'Source', key: 'source', width: 20 },
    { header: 'Content', key: 'content', width: 60 },
  ];

  // Style the header row
  const headerRow = sheet.getRow(1);
  headerRow.font = { bold: true, size: 12 };
  headerRow.fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FF4472C4' },
  };
  headerRow.font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };

  // Add extracted text rows
  sheet.addRow({ source: 'PDF Text Extraction', content: 'Employee Handbook' });
  sheet.addRow({ source: 'PDF Text Extraction', content: 'Welcome to the company. This handbook outlines our policies.' });
  sheet.addRow({ source: 'OCR (Tesseract)', content: 'Employee Handbook' });
  sheet.addRow({ source: 'OCR (Tesseract)', content: 'Welcome to the company. This handbook outlines our policies.' });

  // Auto-fit row heights
  sheet.eachRow(row => { row.alignment = { vertical: 'middle', wrapText: true }; });

  await workbook.xlsx.writeFile('/workspace/handbook_extracted.xlsx');
  console.log('Excel file created: /workspace/handbook_extracted.xlsx');
}

main().catch(console.error);
